import {test,expect} from './helpers/editor-test';
import {demoProject} from '../src/lib/model';
import {inflationStoryboard} from '../src/lib/inflation-storyboard';
import {exportStoryboard} from '../src/lib/storyboard';
import {DEFAULT_PROJECT_URL} from '../src/lib/startup-project';
import {readFile} from 'node:fs/promises';
const fixture=()=>({...demoProject(),storyboard:inflationStoryboard()});
async function setup(page:import('@playwright/test').Page){
 await page.addInitScript(()=>localStorage.setItem('jacktools.scenescript.storage-consent.v1','yes'));
 await page.addInitScript(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async(value:string)=>{(window as any).boardCopied=value;}}}));
 await page.route('**'+DEFAULT_PROJECT_URL,route=>route.fulfill({contentType:'application/json',body:JSON.stringify(fixture())}));await page.goto('/de/');await page.locator('#open-storyboard').click();
}
async function approveTab(page:import('@playwright/test').Page,kind:string){await page.locator(`[data-board-tab=${kind}]`).click();const ids=await page.locator('[data-board-item]').evaluateAll(buttons=>buttons.map(b=>(b as HTMLElement).dataset.boardItem!));for(const id of ids){await page.locator(`[data-board-item="${id}"]`).click();await page.locator('[data-board-review]:has([aria-current=true])').getByRole('switch',{name:'Freigegeben',exact:true}).check();}if(ids.length)await page.locator(`[data-board-item="${ids[0]}"]`).click();}
async function approveResources(page:import('@playwright/test').Page){for(const kind of ['characters','objects','settings'])await approveTab(page,kind);}
async function addComment(page:import('@playwright/test').Page,scope:import('@playwright/test').Locator|undefined,text:string){await (scope??page.locator('#storyboard-content')).getByRole('button',{name:'Kommentar hinzufügen',exact:true}).click();await expect(page.locator('#storyboard-field-heading')).toHaveText('Kommentar hinzufügen');await page.locator('#storyboard-field-text').fill(text);await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-field-dialog')).not.toBeVisible();}
const copied=async(page:import('@playwright/test').Page)=>JSON.parse(await page.evaluate(()=>(window as any).boardCopied as string));
test('plan cards, feedback, image manifests and AI revisions preserve user comments and executable video',async({page})=>{
 await setup(page);await expect(page.locator('#storyboard-content')).toContainText('Inflation Explained with Chocolate');await page.locator('[data-board-tab=objects]').click();await expect(page.locator('[data-board-item]')).toHaveCount(2);await page.locator('[data-board-tab=shots]').click();await expect(page.locator('[data-board-item]')).toHaveCount(3);await expect(page.locator('.board-sketch')).toHaveCount(1);
 const first=page.locator('.board-card').first();await addComment(page,first,'Make the opening brighter.');
 await page.locator('#storyboard-feedback').click();const json=await copied(page);expect(JSON.stringify(json)).not.toContain('data:image');expect(json.board.shots[0].comments[0].text).toBe('Make the opening brighter.');
 json.board.shots[0].comments[0].text='AI must not rewrite this';json.board.shots[0].comments[0].resolved=true;json.board.shots[0].comments[0].reply='Brightened the opening.';json.board.shots[0].action+=' Add brighter light.';
 await page.locator('#storyboard-json-open').click();await page.locator('#storyboard-json').fill(JSON.stringify(json));await page.locator('#storyboard-import').click();await expect(first).toContainText('Brightened the opening.');await expect(first.locator('.board-comment-text')).toHaveText('Make the opening brighter.');await expect(first.getByRole('switch',{name:'Erledigt',exact:true})).not.toBeChecked();await expect(page.locator('.board-sketch')).toHaveCount(1);
 await page.locator('#storyboard-save').click();await expect(page.locator('#storyboard-dialog')).not.toBeVisible();const download=page.waitForEvent('download');await page.locator('#save-project').click();const d=await download;const native=JSON.parse(await readFile((await d.path())!,'utf8'));expect(native.scenes).toEqual(fixture().scenes);expect(native.storyboard.shots[0].comments[0].text).toBe('Make the opening brighter.');expect(native.storyboard.images.start.data).toContain('data:image');
 await page.waitForTimeout(700);await page.reload();await page.locator('#open-storyboard').click();await page.locator('[data-board-tab=shots]').click();await expect(page.locator('.board-card').first()).toContainText('Brightened the opening.');
});
test('paste and file validation show a copyable error and keep the plan intact',async({page})=>{
 await setup(page);await page.locator('#storyboard-json-open').click();const bad=JSON.parse(exportStoryboard(inflationStoryboard()));bad.board.shots[0].duration=0;await page.locator('#storyboard-json').fill(JSON.stringify(bad));await page.locator('#storyboard-import').click();await expect(page.locator('#storyboard-exchange-error')).toBeVisible();await expect(page.locator('#storyboard-exchange-error')).toHaveValue(/shots\[0\].duration/);await expect(page.locator('#storyboard-exchange-error')).toHaveAttribute('readonly','');
 await page.locator('#storyboard-file').setInputFiles({name:'bad.json',mimeType:'application/json',buffer:Buffer.from(JSON.stringify(bad))});await expect(page.locator('#storyboard-exchange-error')).toHaveValue(/shots\[0\].duration/);await page.locator('#storyboard-exchange-close').click();await page.locator('[data-board-tab=shots]').click();await expect(page.locator('[data-board-item]')).toHaveCount(3);
});
test('approval, complete backup, save and undo work independently from the existing video',async({page})=>{
 await setup(page);await expect(page.locator('#storyboard-approve')).toBeDisabled();await approveResources(page);await approveTab(page,'shots');await page.locator('#storyboard-approve').click();await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','true');
 const downloading=page.waitForEvent('download');await page.locator('#storyboard-download').click();const download=await downloading;const backup=JSON.parse(await readFile((await download.path())!,'utf8'));expect(backup.board.images.start.data).toContain('data:image');await page.locator('#storyboard-save').click();await expect(page.locator('#undo-project')).toBeEnabled();await page.locator('#undo-project').click();await page.locator('#open-storyboard').click();await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','false');await page.locator('#storyboard-close').click();await page.locator('#redo-project').click();await page.locator('#open-storyboard').click();await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','true');
});
test('a project with no storyboard can import a separate plan; stale editor sessions cannot overwrite newer changes',async({page})=>{
 await page.goto('/de/');await page.locator('#open-storyboard').click();await expect(page.locator('#storyboard-content')).toContainText('Noch keine KI-Vorschläge');await page.locator('#storyboard-file').setInputFiles({name:'plan.json',mimeType:'application/json',buffer:Buffer.from(exportStoryboard(inflationStoryboard(),true))});await expect(page.locator('#storyboard-content')).toContainText('Inflation Explained with Chocolate');
 // Simulate a concurrent project edit while the modal's draft is open.
 await page.evaluate(()=>{const title=document.getElementById('project-title') as HTMLInputElement;title.value='Concurrent edit';title.dispatchEvent(new Event('input',{bubbles:true}));});await page.locator('#storyboard-save').click();await expect(page.locator('#storyboard-error')).toHaveValue(/inzwischen geändert/);page.once('dialog',d=>d.accept());await page.keyboard.press('Escape');await expect(page.locator('#storyboard-dialog')).not.toBeVisible();await expect(page.locator('#project-title')).toHaveValue('Concurrent edit');
});
test('open comments block final approval and cancellation keeps a saved plan unchanged',async({page})=>{
 await setup(page);await approveResources(page);await approveTab(page,'shots');const first=page.locator('.board-card').first();await addComment(page,first,'Please brighten this shot.');await expect(page.locator('#storyboard-approve')).toBeDisabled();await first.getByRole('switch',{name:'Erledigt',exact:true}).check();await expect(page.locator('#storyboard-approve')).toBeEnabled();
 const dimensions=await page.locator('#storyboard-save').evaluate(e=>({width:e.clientWidth,scroll:e.scrollWidth}));expect(dimensions.scroll).toBeLessThanOrEqual(dimensions.width);await expect(page.locator('#storyboard-content input:not([type=checkbox])')).toHaveCount(0);
 page.once('dialog',d=>d.dismiss());await page.locator('#storyboard-close').click();await expect(page.locator('#storyboard-dialog')).toBeVisible();page.once('dialog',d=>d.accept());await page.locator('#storyboard-close').click();await page.locator('#open-storyboard').click();await page.locator('[data-board-tab=shots]').click();await expect(page.locator('.board-comment')).toHaveCount(0);
});
async function editText(page:import('@playwright/test').Page,key:string,value:string){await page.locator(`[data-board-edit="${key}"]`).click();await expect(page.locator('#storyboard-field-dialog')).toBeVisible();await page.locator('#storyboard-field-text').fill(value);await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-field-dialog')).not.toBeVisible();}
test('pencil overlays edit multiline text, format and duration without changing the video',async({page})=>{
 await setup(page);await editText(page,'story','My beginning.\n\nMy ending.');await expect(page.locator('#storyboard-content')).toContainText('My beginning.');await expect(page.locator('[data-board-edit=story]')).toBeFocused();
 await page.locator('[data-board-edit=story]').click();await expect(page.locator('#storyboard-field-text')).toHaveValue('My beginning.\n\nMy ending.');await page.locator('#storyboard-field-text').fill('Discard me');await page.keyboard.press('Escape');await expect(page.locator('#storyboard-dialog')).toBeVisible();await expect(page.locator('#storyboard-content')).not.toContainText('Discard me');
 await editText(page,'audience','For curious beginners');await page.locator('[data-board-edit=language]').click();await expect(page.locator('#storyboard-field-text')).not.toBeVisible();await page.locator('#storyboard-field-select').selectOption('German');await page.locator('#storyboard-field-apply').click();await editText(page,'title','A new title');
 await page.locator('[data-board-edit=format]').click();await expect(page.locator('#storyboard-field-text')).not.toBeVisible();await page.locator('#storyboard-field-select').selectOption('square');await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-content')).toContainText('Quadratisch · 1:1');
 await page.locator('[data-board-edit=duration]').click();await page.locator('#storyboard-field-number').fill('0');await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-field-dialog')).toBeVisible();await page.locator('#storyboard-field-number').fill('45.5');await page.locator('#storyboard-field-apply').click();
 await page.locator('#storyboard-save').click();const downloading=page.waitForEvent('download');await page.locator('#save-project').click();const download=await downloading;const native=JSON.parse(await readFile((await download.path())!,'utf8'));expect(native.storyboard.story).toBe('My beginning.\n\nMy ending.');expect(native.storyboard.format).toBe('square');expect(native.storyboard.duration).toBe(45.5);expect(native.storyboard.audience).toBe('For curious beginners');expect(native.storyboard.language).toBe('German');expect(native.format).toBe('landscape');expect(native.title).toBe(fixture().title);expect(native.scenes).toEqual(fixture().scenes);
 await page.waitForTimeout(700);await page.reload();await page.locator('#open-storyboard').click();await expect(page.locator('#storyboard-content')).toContainText('Quadratisch · 1:1');await expect(page.locator('#storyboard-content')).toContainText('My ending.');
});
test('users can prefill a fresh storyboard with characters, settings and shots',async({page})=>{
 await page.goto('/de/');await page.locator('#open-storyboard').click();await editText(page,'story','A robot lands on the moon.');await page.locator('[data-board-tab=characters]').click();await page.getByRole('button',{name:'Charakter hinzufügen',exact:true}).click();await page.locator('#storyboard-field-text').fill('Luna');await page.locator('#storyboard-field-apply').click();const characterKey=await page.locator('[data-board-edit$="-description"]').getAttribute('data-board-edit');await editText(page,characterKey!,'A cheerful blue robot.');await page.locator('[data-board-tab=objects]').click();await page.getByRole('button',{name:'Objekt hinzufügen',exact:true}).click();await page.locator('#storyboard-field-text').fill('Mission key');await page.locator('#storyboard-field-apply').click();
 await page.locator('[data-board-tab=settings]').click();await page.getByRole('button',{name:'Kulisse hinzufügen',exact:true}).click();await page.locator('#storyboard-field-text').fill('Moon base');await page.locator('#storyboard-field-apply').click();
 await page.locator('[data-board-tab=shots]').click();await page.locator('#storyboard-content').getByRole('button',{name:'Szene hinzufügen',exact:true}).click();await page.locator('#storyboard-field-text').fill('Landing');await page.locator('#storyboard-field-apply').click();const card=page.locator('.board-card');const id=await card.getAttribute('data-shot-id');await editText(page,id+'-action','Luna waves at the camera.');await editText(page,id+'-camera','Slow push-in.');await editText(page,id+'-audio','Soft landing sound.');
 for(const kind of ['characters','objects','settings']){await page.locator(`[data-board-edit="${id}-${kind}"]`).click();await page.locator('#storyboard-field-choices input').check();await page.locator('#storyboard-field-apply').click();}await expect(card).toContainText('Luna');await expect(card).toContainText('Moon base');
 await page.evaluate(()=>Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async(value:string)=>{(window as any).boardCopied=value;}}}));await page.locator('#storyboard-feedback').click();const json=await copied(page);expect(json.board.characters[0].description).toBe('A cheerful blue robot.');expect(json.board.shots[0].characters).toEqual([json.board.characters[0].id,json.board.characters[1].id]);expect(json.board.characters[0].kind).toBe('character');expect(json.board.characters[1].kind).toBe('object');expect(json.board.shots[0].settings).toEqual([json.board.settings[0].id]);expect(json.board.shots[0].audio).toBe('Soft landing sound.');expect(json.board.format).toBe('landscape');
});
test('content edits reset affected approvals; cancel and unchanged values do not',async({page})=>{
 await setup(page);await approveResources(page);await approveTab(page,'shots');await page.locator('#storyboard-approve').click();
 const card=page.locator('.board-card').first();await page.locator('[data-board-edit=hook-action]').click();await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','true');
 await page.locator('[data-board-edit=hook-action]').click();await page.locator('#storyboard-field-text').fill('Cancelled');await page.locator('#storyboard-field-cancel').click();await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','true');
 await editText(page,'hook-action','A revised opening');await expect(page.locator('[data-board-review]:has([aria-current=true])').getByRole('switch',{name:'Freigegeben',exact:true})).not.toBeChecked();await expect(page.locator('[data-board-item=reveal]')).toHaveAttribute('data-approved','true');await expect(page.locator('#storyboard-approve')).toHaveAttribute('aria-pressed','false');
 await page.locator('[data-board-tab=story]').click();await editText(page,'style','Watercolour');await page.locator('[data-board-tab=shots]').click();for(const box of await page.locator('#storyboard-content input[type=checkbox]').all())await expect(box).not.toBeChecked();
});
test('field overlays detect concurrent edits and keep user input available',async({page})=>{
 await setup(page);await page.locator('[data-board-edit=story]').click();await page.locator('#storyboard-field-text').fill('My unsaved text');await page.evaluate(()=>{const title=document.getElementById('project-title') as HTMLInputElement;title.value='Changed outside';title.dispatchEvent(new Event('input',{bubbles:true}));});await page.locator('#storyboard-field-apply').click();await expect(page.locator('#storyboard-field-error')).toContainText('inzwischen geändert');await expect(page.locator('#storyboard-field-text')).toHaveValue('My unsaved text');await page.locator('#storyboard-field-cancel').click();await expect(page.locator('#storyboard-dialog')).toBeVisible();
});
test('global actions form a fixed icon toolbar with localized tooltips and an icon-only save footer',async({page})=>{
 await setup(page);await expect(page.locator('[data-board-tab=story]')).toHaveText('Projekt');await expect(page.locator('[data-board-edit=story]')).toHaveAttribute('title','Bearbeiten: Ganze Geschichte');const toolbar=page.getByRole('toolbar',{name:'Storyboard-Aktionen'});await expect(toolbar).toBeVisible();await expect(toolbar.locator('button')).toHaveCount(7);await expect(page.locator('#storyboard-state')).toHaveCount(0);await expect(page.locator('#storyboard-review')).toHaveCount(0);expect(await page.locator('#storyboard-approve-hint').evaluate(e=>e.getBoundingClientRect().height)).toBeLessThanOrEqual(1);
 const header=page.locator('#storyboard-dialog>.json-header'),hint=page.locator('#storyboard-hint');const toolbarBounds=await toolbar.boundingBox(),headerBounds=await header.boundingBox(),hintBounds=await hint.boundingBox();
 expect(toolbarBounds!.y).toBeGreaterThanOrEqual(hintBounds!.y+hintBounds!.height);expect(Math.abs(toolbarBounds!.y+toolbarBounds!.height-(headerBounds!.y+headerBounds!.height-1))).toBeLessThan(2);
 expect(await toolbar.evaluate(e=>getComputedStyle(e).backgroundColor)).not.toBe(await header.evaluate(e=>getComputedStyle(e).backgroundColor));
 for(const button of await toolbar.locator('button').all()){
  const title=await button.getAttribute('title');expect(title?.length).toBeGreaterThan(0);if(await button.getAttribute('id')==='storyboard-approve'){await expect(button).toHaveAttribute('aria-label','Storyboard freigeben');expect(title).toContain('Charaktere/Objekte');}else await expect(button).toHaveAttribute('aria-label',title!);await expect(button.locator('svg[aria-hidden=true]')).toHaveCount(1);expect((await button.textContent())?.trim()).toBe('');
 }
 const save=page.locator('#storyboard-save');await expect(save).toHaveAttribute('title','Änderungen speichern');await expect(save).toHaveAttribute('aria-label','Änderungen speichern');expect((await save.textContent())?.trim()).toBe('');await expect(save.locator('svg')).toHaveCount(1);
 await toolbar.locator('#storyboard-feedback').click();expect((await copied(page)).board.title).toBe('Inflation Explained with Chocolate');
 await expect(toolbar.locator('#storyboard-json-open')).toHaveAttribute('aria-haspopup','dialog');await toolbar.locator('#storyboard-json-open').click();await expect(page.getByRole('dialog',{name:'Austausch mit der KI',exact:true})).toBeVisible();await expect(page.locator('#storyboard-json')).toBeFocused();await page.locator('#storyboard-exchange-close').click();await expect(page.locator('#storyboard-json')).not.toBeVisible();await expect(toolbar.locator('#storyboard-json-open')).toBeFocused();
 await page.locator('[data-board-tab=shots]').click();await page.locator('.board-card').last().getByRole('button',{name:'Kommentar hinzufügen',exact:true}).scrollIntoViewIfNeeded();
 const bounds=await toolbar.boundingBox(),footer=await save.boundingBox();expect(bounds!.y).toBeGreaterThanOrEqual(0);expect(footer!.y+footer!.height).toBeLessThanOrEqual(page.viewportSize()!.height);await expect(page.locator('#storyboard-dialog>.json-footer #storyboard-close')).toBeVisible();const closeBounds=await page.locator('#storyboard-close').boundingBox();expect(closeBounds!.x).toBeLessThan(footer!.x);expect(closeBounds!.y).toBe(footer!.y);await expect(page.locator('#storyboard-close')).toHaveAttribute('title','Schließen');
 expect(await toolbar.evaluate(e=>e.scrollWidth)).toBeLessThanOrEqual(await toolbar.evaluate(e=>e.clientWidth));expect((await save.boundingBox())!.width).toBe(44);
 await page.locator('#storyboard-close').click();await expect(page.locator('#storyboard-dialog')).not.toBeVisible();
});
